"""Builds public/og.png (1200x630), the preview card shown when a link is shared.
Run: python3 scripts/make-og.py"""
from PIL import Image, ImageDraw, ImageFilter, ImageFont

W, H = 1200, 630
BG = (247, 247, 245)
INK = (24, 24, 27)
MUTED = (113, 113, 122)

def font(size, bold=False):
    # Helvetica ships with macOS; the card is only regenerated by hand, so a system font is fine.
    return ImageFont.truetype('/System/Library/Fonts/Helvetica.ttc', size, index=1 if bold else 0)

img = Image.new('RGB', (W, H), BG)
d = ImageDraw.Draw(img)

icon = Image.open('public/icon.png').convert('RGBA').resize((64, 64), Image.LANCZOS)
img.paste(icon, (64, 64), icon)
d.text((144, 68), 'Sheaf', font=font(50, True), fill=INK)
d.text((64, 214), 'Write first.', font=font(54, True), fill=INK)
d.text((64, 292), 'Extend the rest.', font=font(54, True), fill=(37, 99, 235))
d.text((64, 410), 'A free, open source', font=font(28), fill=MUTED)
d.text((64, 448), 'Markdown editor with diagrams,', font=font(28), fill=MUTED)
d.text((64, 486), 'math, themes and plugins.', font=font(28), fill=MUTED)

# The screenshot bleeds off the right and bottom edges, which reads as "there is more app than fits".
shot = Image.open('public/screens/editor.png').convert('RGB')
sw = 700
shot = shot.resize((sw, round(shot.height * sw / shot.width)), Image.LANCZOS)
mask = Image.new('L', shot.size, 0)
ImageDraw.Draw(mask).rounded_rectangle((0, 0, *shot.size), 18, fill=255)
x, y = 600, 170
shadow = Image.new('RGBA', (W, H), (0, 0, 0, 0))
ImageDraw.Draw(shadow).rounded_rectangle((x, y + 8, x + sw, y + 8 + shot.height), 18, fill=(0, 0, 0, 70))
img = Image.alpha_composite(img.convert('RGBA'), shadow.filter(ImageFilter.GaussianBlur(20))).convert('RGB')
img.paste(shot, (x, y), mask)
img.save('public/og.png', optimize=True)
